globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"year":2014,"grade":"9-10","title":"Человек и природа","tasksFile":"9-10_2014.pdf","answersFile":"reviewed-9-10.pdf","subject":"chip","contest":"Человек и природа","letters":"АБВГД","count":30,"language":"ru","points":3,"reviewedKey":true}, [{"number":1,"question":"Сколько континентов омывает Индийский океан, если воды вокруг Антарктиды считать отдельным Южным океаном?","choices":["1","2","3","5","6"],"answer":2,"points":3,"title":"Материки Индийского океана","steps":["Индийский океан омывает восток Африки и запад Австралии. На севере к нему выходят берега Евразии.","В принятой схеме пяти океанов воды у Антарктиды относят к Южному океану. Поэтому у Индийского три материка-соседа."],"adaptation":"Указана система из пяти океанов."},{"number":2,"question":"Европейцы впервые достигли Тихого океана в составе экспедиции под командованием","choices":["Христофора Колумба","Фернана Магеллана","Васко Нуньеса де Бальбоа","Васко да Гамы","Ивана Москвитина"],"answer":2,"points":3,"title":"Кто вышел к Тихому океану","steps":["В 1513 году экспедиция Бальбоа пересекла Панамский перешеек с Атлантической стороны. Европейцы вышли к морю на противоположном берегу.","Бальбоа назвал увиденное Южным морем. До плавания Магеллана по этим водам оставалось несколько лет."]},{"number":3,"question":"Часть света Антарктида изображена на рисунке","choices":["","","","",""],"answer":3,"points":3,"title":"Контур Антарктиды","steps":["Антарктида окружает Южный полюс. Если смотреть на неё сверху, виден почти сплошной массив суши и узкий выступ.","На рисунке Г этот выступ — Антарктический полуостров, направленный к Южной Америке."],"optionFigures":[{"src":"assets/chip/2014/9-10-03-1.webp","detailSrc":"assets/chip/2014/detail/9-10-03-1.svg","width":480,"height":431,"pixelWidth":920,"pixelHeight":826,"alt":"Широкая восточная часть материка с несколькими южными полуостровами."},{"src":"assets/chip/2014/9-10-03-2.webp","detailSrc":"assets/chip/2014/detail/9-10-03-2.svg","width":480,"height":424,"pixelWidth":920,"pixelHeight":812,"alt":"Материк с широким севером и узким югом, справа большой остров."},{"src":"assets/chip/2014/9-10-03-3.webp","detailSrc":"assets/chip/2014/detail/9-10-03-3.svg","width":480,"height":431,"pixelWidth":920,"pixelHeight":826,"alt":"Вытянутый материк с неровной северной и западной границей."},{"src":"assets/chip/2014/9-10-03-4.webp","detailSrc":"assets/chip/2014/detail/9-10-03-4.svg","width":480,"height":428,"pixelWidth":920,"pixelHeight":819,"alt":"Округлая масса суши с одним узким выступом."},{"src":"assets/chip/2014/9-10-03-5.webp","detailSrc":"assets/chip/2014/detail/9-10-03-5.svg","width":480,"height":428,"pixelWidth":920,"pixelHeight":819,"alt":"Компактный материк и несколько соседних островов."}]},{"number":4,"question":"Кто оставил письменные донесения о плавании 1648 года через пролив между Азией и Северной Америкой, позже названный Беринговым?","choices":["Владимир Атласов","Витус Беринг","Семён Дежнёв","Джеймс Кук","Федот Попов"],"answer":2,"points":3,"title":"Кто описал пролив","steps":["Семён Дежнёв участвовал в плавании вокруг северо-востока Азии в 1648 году. В его донесениях сохранились сведения о маршруте.","Плавание показало, что Азия и Северная Америка разделены морским проходом. Позже пролив получил имя Витуса Беринга."],"adaptation":"Уточнено, по какому источнику определяется первенство."},{"number":5,"question":"В романе Жюля Верна «Путешествие к центру Земли» участники экспедиции обнаружили в сердцевине нашей планеты, что «между деревьями двигались какие-то … исполинские звери, стадо мастодонтов». Но согласно современным представлениям в центре Земли находится","choices":["пустота","железо-никелевый сплав с твёрдым внутренним и жидким внешним ядром","высокотемпературный силикатный расплав с присутствием металлов, а также оксидов углерода, фтора и хлора","железо-никелевый сплав с жидким внутренним и твёрдым внешним ядром","вода в виде ледяной глыбы"],"answer":1,"points":3,"title":"Из чего состоит ядро Земли","steps":["Данные о прохождении сейсмических волн показывают, что внешняя и внутренняя части ядра ведут себя по-разному. Внешнее ядро жидкое, а внутреннее твёрдое.","Основу обеих частей составляет железо с никелем и примесями. Высокое давление в центре позволяет внутреннему ядру оставаться твёрдым."]},{"number":6,"question":"На картине русского художника и путешественника В. В. Верещагина изображена площадь средневекового города, который был столицей империи и центром науки. Это","choices":["Ашхабад","Дели","Лондон","Петербург","Самарканд"],"answer":4,"points":3,"title":"Город на картине Верещагина","steps":["На площади видны среднеазиатские здания, в том числе башни и стены с цветной отделкой. В Средние века город был столицей государства Тимура.","При Улугбеке здесь развивалась астрономия. Обе подсказки указывают на Самарканд."],"figure":{"src":"assets/chip/2014/9-10-06.webp","detailSrc":"assets/chip/2014/detail/9-10-06.webp","width":200,"height":127,"pixelWidth":200,"pixelHeight":127,"alt":"Площадь среднеазиатского города, башни и стены с цветной изразцовой отделкой."}},{"number":7,"question":"Какое из этих растений встречается в пустынях?","choices":["","","","",""],"answer":4,"points":3,"title":"Растение пустыни","steps":["В варианте Д видно растение с розеткой толстых жёстких листьев. Такие листья помогают накопить воду и замедляют её потерю.","Это агава или близкое к ней растение сухих областей. По форме она отличается от болотных и лесных растений других вариантов."],"optionFigures":[{"src":"assets/chip/2014/9-10-07-1.webp","detailSrc":"assets/chip/2014/detail/9-10-07-1.webp","width":137,"height":105,"pixelWidth":137,"pixelHeight":105,"alt":"Крупные листья на поверхности воды и необычные бурые выросты."},{"src":"assets/chip/2014/9-10-07-2.webp","detailSrc":"assets/chip/2014/detail/9-10-07-2.webp","width":139,"height":105,"pixelWidth":139,"pixelHeight":105,"alt":"Зелёное растение с трубчатыми листьями."},{"src":"assets/chip/2014/9-10-07-3.webp","detailSrc":"assets/chip/2014/detail/9-10-07-3.webp","width":139,"height":105,"pixelWidth":139,"pixelHeight":105,"alt":"Кисти тёмных и красных сборных ягод."},{"src":"assets/chip/2014/9-10-07-4.webp","detailSrc":"assets/chip/2014/detail/9-10-07-4.webp","width":138,"height":105,"pixelWidth":138,"pixelHeight":105,"alt":"Лиловые цветки на коротких стеблях среди мха."},{"src":"assets/chip/2014/9-10-07-5.webp","detailSrc":"assets/chip/2014/detail/9-10-07-5.webp","width":138,"height":105,"pixelWidth":138,"pixelHeight":105,"alt":"Розетка из толстых жёстких листьев."}]},{"number":8,"question":"В России крестьяне называли это растение «чёртовым яблоком», а в середине XIX века даже прокатилась волна бунтов против разведения этой культуры. Это","choices":["капуста","томат","брюква","картофель","подсолнечник"],"answer":3,"points":3,"title":"Чёртово яблоко","steps":["В XIX веке власти расширяли посадки нового для многих крестьян растения. Против принудительного выращивания происходили волнения.","Эти волнения известны как картофельные бунты. «Чёртовым яблоком» в вопросе назван картофель."]},{"number":9,"question":"Распашка целинных земель привела к эрозийным процессам и к потере почвой её главного свойства – плодородия. Это произошло при освоении новых территорий","choices":["Австралии","Северной Америки","Дальнего Востока","Казахстана","Нидерландов"],"answer":3,"points":3,"title":"Распашка целины","steps":["В ходе советского освоения целины распахали большие площади степи. После утраты плотного дернового покрова сухую почву легче уносит ветер.","Крупнейшие районы этой кампании находились в северном Казахстане. Ветровая эрозия стала одной из её проблем."]},{"number":10,"question":"Почётное звание «Снежный барс России» присуждается","choices":["альпинисту, если он покорил 10 знаменитых горных вершин на территории России","биологу, если он вырастил в неволе не менее 10 снежных барсов","журналисту, если он опубликовал 10 статей о животных, занесённых в «Красную книгу России»","математику, если он написал 10 учебников","фотографу, если он сделал фотоснимки 10 ирбисов в российских горах"],"answer":0,"points":3,"title":"Звание для альпиниста","steps":["В названии звания «Снежный барс России» слово «барс» образно связывает человека с горными вершинами.","Звание присваивалось за восхождения на десять определённых российских вершин. Среди перечисленных подходит альпинист."]},{"number":11,"question":"По какой параллели можно обогнуть Землю по воде, не встречая суши и не проходя через Арктику?","choices":["85° северной широты","75° северной широты","10° северной широты","50° южной широты","60° южной широты"],"answer":4,"points":4,"title":"Параллель в открытом океане","steps":["На 10° северной и 50° южной широты путь пересекает сушу. Северные варианты либо проходят через острова, либо идут среди арктических льдов.","Параллель 60° южной широты проходит по открытым водам вокруг Антарктиды. Условия плавания зависят от погоды и сезонных льдов."],"adaptation":"Исключено предположение о гарантированно свободном ото льда маршруте."},{"number":12,"question":"На картине Ю. Циглера «Собачья упряжка» изображена высочайшая вершина Северной Америки. Это","choices":["Аконкагуа","Мак-Кинли","Митчелл","Попокатепетль","Сагарматха"],"answer":1,"points":4,"title":"Высшая вершина Аляски","steps":["На картине Юрия Циглера показана вершина Аляскинского хребта. Её высота около 6190 метров.","В буклете она названа Мак-Кинли. Для этой же горы употребляют традиционное название Денали."],"figure":{"src":"assets/chip/2014/9-10-12.webp","detailSrc":"assets/chip/2014/detail/9-10-12.webp","width":480,"height":376,"pixelWidth":505,"pixelHeight":396,"alt":"Снежная горная вершина и собачья упряжка на переднем плане."}},{"number":13,"question":"Чарлз Дарвин в книге «Путешествие натуралиста вокруг света…» писал: «Леса кажутся светлыми, лишёнными тени». Это","choices":["эвкалиптовые леса","темнохвойная тайга","ликвидамбаровые леса","дубовые леса","грабовые леса"],"answer":0,"points":4,"title":"Светлый лес Дарвина","steps":["У многих эвкалиптов листья повернуты так, что в полдень меньше обращены плоскостью к Солнцу. Между кронами остаются просветы.","Поэтому такой австралийский лес кажется светлым. Дарвин описывал эвкалиптовые леса."]},{"number":14,"question":"Знаменитые Геркулесовы столбы – это","choices":["звёзды по сторонам созвездия Геркулес","пограничные столбы, обозначающие пределы Финикийского государства","памятник, поставленный Гераклом после очистки авгиевых конюшен","путевые столбы, установленные Гераклом по дороге из Афин в Дельфы","символ предела мира"],"answer":4,"points":4,"title":"Граница знакомого мира","steps":["Геркулесовыми столбами античные авторы называли возвышенности по обе стороны выхода из Средиземного моря. Сейчас этот проход знают как Гибралтарский пролив.","Для древних мореплавателей столбы обозначали край привычного пространства за пределами Средиземноморья. Отсюда образ предела мира."]},{"number":15,"question":"Кого из этих путешественников можно отнести к началу Нового времени по первому трансатлантическому плаванию его экспедиции в 1492 году?","choices":["Амундсен","Колумб","Кук","Неарх","Пржевальский"],"answer":1,"points":4,"title":"Путешественник Нового времени","steps":["Среди названных путешественников с началом постоянных связей Европы и Америки связан Колумб. Его первое трансатлантическое плавание состоялось в 1492 году.","Это путешествие стало одним из условных рубежей между Средневековьем и Новым временем. Так объясняется предложенная в вопросе характеристика."],"adaptation":"Вопрос привязан к историческому событию, которое точно устанавливается."},{"number":16,"question":"По распространённому преданию, минерал с Урала назвали в честь наследника российского престола Александра. При дневном свете он зелёный, а при свете лампы становится красновато-лиловым. Как его называют?","choices":["александрит","малахит","никколит","опал","цаворит"],"answer":0,"points":4,"title":"Камень, меняющий цвет","steps":["Этот минерал в дневном свете обычно кажется зелёным, а при освещении лампой накаливания становится красноватым или фиолетовым.","Это александрит, разновидность хризоберилла. Его название связано с именем Александра II."],"adaptation":"Обстоятельства наименования приведены как предание."},{"number":17,"question":"«Поэзия — та же добыча ... В грамм добыча, в год труды». Маяковский сравнил труд поэта с работой Пьера и Марии Кюри, которые переработали несколько тонн сырья для получения примерно 0,1 г соли какого элемента?","choices":["ванадия","золота","палладия","радия","урана"],"answer":3,"points":4,"title":"Добыча радия","steps":["Пьер и Мария Кюри перерабатывали остатки урановой руды, чтобы выделить из них радиоактивное вещество. Его было очень мало по отношению к массе сырья.","Речь о соли радия. Маяковский сравнил поиск точного поэтического слова с такой кропотливой работой."],"adaptation":"Стихотворная цитата сверена с текстом Маяковского."},{"number":18,"question":"Кто из этих животных не обитает в природе в Африке?","choices":["","","","",""],"answer":1,"points":4,"title":"Животные Африки","steps":["На снимке Б ленивец: он держится за ветвь длинными изогнутыми когтями. Ленивцы в природе живут в Центральной и Южной Америке.","Другие фотографии показывают животных, которые встречаются в природе в Африке, например гориллу и окапи. Исключение — ленивец."],"adaptation":"Уточнено, что сравниваются природные ареалы.","optionFigures":[{"src":"assets/chip/2014/9-10-18-1.webp","detailSrc":"assets/chip/2014/detail/9-10-18-1.webp","width":133,"height":105,"pixelWidth":133,"pixelHeight":105,"alt":"Светло-жёлтая пятнистая кошка на поляне."},{"src":"assets/chip/2014/9-10-18-2.webp","detailSrc":"assets/chip/2014/detail/9-10-18-2.webp","width":135,"height":105,"pixelWidth":135,"pixelHeight":105,"alt":"Серый зверь висит на ветке, обхватив её длинными лапами."},{"src":"assets/chip/2014/9-10-18-3.webp","detailSrc":"assets/chip/2014/detail/9-10-18-3.webp","width":133,"height":105,"pixelWidth":133,"pixelHeight":105,"alt":"Крупная тёмная человекообразная обезьяна."},{"src":"assets/chip/2014/9-10-18-4.webp","detailSrc":"assets/chip/2014/detail/9-10-18-4.webp","width":134,"height":105,"pixelWidth":134,"pixelHeight":105,"alt":"Жёлтая кошка с тёмными пятнами лежит в траве."},{"src":"assets/chip/2014/9-10-18-5.webp","detailSrc":"assets/chip/2014/detail/9-10-18-5.webp","width":134,"height":105,"pixelWidth":134,"pixelHeight":105,"alt":"Тёмное копытное с белыми полосами на ногах."}]},{"number":19,"question":"Какие насекомые известны тем, что микробы их кишечника образуют водород при переработке древесной пищи?","choices":["богомолы","водные жуки","навозные жуки","стрекозы","термиты"],"answer":4,"points":4,"title":"Водород в природе","steps":["Термиты питаются растительным материалом. В их кишечнике живут микроорганизмы, помогающие перерабатывать целлюлозу.","При такой переработке некоторые микроорганизмы образуют водород. Нужное насекомое из списка — термит."],"adaptation":"Убрана ненадёжная датировка появления явления."},{"number":20,"question":"Почему при поиске нефтяных залежей геологи исследуют верхние участки выпуклых складок горных пород, если сверху лежит непроницаемый слой?","choices":["там лучше видно, куда бурить","скважину на поверхности не затопит при наводнении","так удобнее отвести буровой раствор","нефть может скапливаться под непроницаемой породой в верхней части складки","нефть внизу автоматически поднимает буровую вышку"],"answer":3,"points":4,"title":"Залежь под складкой","steps":["Вода, нефть и газ могут занимать разные уровни в порах породы. Нефть обычно менее плотная, чем вода, поэтому может подниматься над ней.","Если сверху есть непроницаемый слой, нефть задерживается в верхней части изгиба подземных пластов. Поверхность земли при этом может быть ровной."],"adaptation":"Различены рельеф поверхности и форма подземных слоёв."},{"number":21,"question":"В эпиграфе к книге Н. Ф. Реймерса «Экология» приведено изречение «Люди погибнут от неумения пользоваться силами природы и от незнания истинного мира». Какому памятнику или источнику его приписывает эпиграф?","choices":["на Фестском диске","на Розеттском камне","на вымпеле, доставленном ракетой на Луну","на пирамиде Хеопса","в предсказаниях Нострадамуса"],"answer":3,"points":5,"title":"Изречение из эпиграфа","steps":["Эпиграф к книге об экологии приписывает изречение надписи на пирамиде Хеопса. Поэтому из памятников в списке выбираем эту пирамиду.","Задача касается атрибуции в книге. Подтверждённой древнеегипетской надписи с этим текстом не установлено."],"adaptation":"Уточнено, что речь об атрибуции в книге, а не о подтверждённой надписи."},{"number":22,"question":"На рисунке — человек умелый (Homo habilis), один из ранних видов рода Homo. Какой из перечисленных более ранних африканских гоминин относится к близкой ему по времени группе?","choices":["австралопитека","неандертальца","человека прямоходящего","дриопитека","человека работающего"],"answer":0,"points":5,"title":"Древние гоминины","steps":["Homo habilis, человек умелый, — один из ранних представителей рода Homo. До него в Африке уже существовали австралопитеки.","Австралопитеки ближе ему по эпохе и месту, чем более древние дриопитеки. Неандертальцы и человек прямоходящий появились позднее."],"adaptation":"Вместо прямой линии происхождения предложено сравнить эпохи и группы.","figure":{"src":"assets/chip/2014/9-10-22.webp","detailSrc":"assets/chip/2014/detail/9-10-22.webp","width":150,"height":181,"pixelWidth":150,"pixelHeight":181,"alt":"Реконструкция лица древнего представителя рода Homo."}},{"number":23,"question":"Какой островной стране в Северной Атлантике начало положило заселение в эпоху викингов выходцами из Скандинавии и Британских островов?","choices":["Дания","Исландия","Швеция","Гренландия","Норвегия"],"answer":1,"points":5,"title":"Страна потомков поселенцев","steps":["Остров в северной Атлантике заселяли выходцы из Скандинавии и с Британских островов. Активное заселение пришлось на эпоху викингов.","На этом острове находится Исландия. Её поселения и язык сохраняют следы скандинавского происхождения."],"adaptation":"Процент заменён историческими данными об основных группах первых поселенцев."},{"number":24,"question":"Период полураспада изотопа углерода-14 составляет около 5700 лет. Если со времени гибели организма прошло 17100 лет, то содержание этого изотопа в объекте уменьшится","choices":["в 3 раза","в 6 раз","в 8 раз","в 9 раз","в бесконечное число раз"],"answer":2,"points":5,"title":"Три периода полураспада","steps":["Делим 17 100 лет на 5700 и получаем три периода полураспада. Каждый раз остаётся половина имевшегося изотопа.","После трёх периодов останется ½ × ½ × ½ = ⅛ исходного количества. Оно уменьшится в восемь раз."]},{"number":25,"question":"Почти все звёзды Большого Квадрата осеннего неба Северного полушария принадлежат одному созвездию. Как называется это созвездие, по которому назван квадрат?","choices":["Пегас","Лебедь","Малая Медведица","Большая Медведица","Андромеда"],"answer":0,"points":5,"title":"Квадрат осеннего неба","steps":["Четыре сравнительно яркие звезды образуют Большой Квадрат. Его используют как ориентир на осеннем небе.","Три звезды квадрата относятся к Пегасу, а четвёртая — к Андромеде. Весь рисунок называют Большим Квадратом Пегаса."],"adaptation":"Уточнено, что звёздный квадрат выходит за пределы одного созвездия."},{"number":26,"question":"Каково примерно расстояние до горизонта у рыбака в открытом море, если его глаза находятся на высоте около метра над водой?","choices":["100 м","1,5 км","3,5 км","10 км","30 км"],"answer":2,"points":5,"title":"Горизонт в открытом море","steps":["Дальность до горизонта зависит от высоты глаз наблюдателя. У сидящего в лодке человека она составляет порядка одного метра.","При радиусе Земли около 6370 км геометрическая оценка √(2Rh) даёт примерно 3,6 км. Ближайший вариант — 3,5 км."],"adaptation":"Добавлена высота глаз для геометрической оценки."},{"number":27,"question":"На гербе Эквадора изображён вулкан","choices":["Этна","Чимборасо","Рейнир","Орисаба","Керинчи"],"answer":1,"points":5,"title":"Вулкан на гербе Эквадора","steps":["На гербе видна заснеженная гора в Андах. Чимборасо находится в Эквадоре и возвышается более чем на 6200 метров.","Она и изображена на гербе. Этна находится в Европе, Рейнир в США, Орисаба в Мексике, а Керинчи на Суматре."],"figure":{"src":"assets/chip/2014/9-10-27.webp","detailSrc":"assets/chip/2014/detail/9-10-27.webp","width":400,"height":480,"pixelWidth":1334,"pixelHeight":1600,"alt":"Герб со щитом. На щите заснеженная гора и река, над щитом птица с раскрытыми крыльями."}},{"number":28,"question":"Корабль ходит между Чукоткой и Аляской. Капитан отмечает только местные пятницы, проведённые хотя бы частично на одном из этих берегов, не более одной отметки за каждую дату на каждом берегу. Сколько таких отметок можно получить за февраль 2014 года, если дни переходов выбрать подходящим образом?","choices":["4","5","8","9","10"],"answer":2,"points":5,"title":"Пятницы на двух берегах","steps":["В феврале 2014 года 28 дней, то есть ровно четыре недели. В местном календаре каждого берега поэтому четыре пятницы.","Если в каждую пятницу сначала побывать на Чукотке, а затем пересечь линию перемены дат на восток и оказаться на Аляске в пятницу по местному времени, получится 4 + 4 = 8 отметок."],"adaptation":"Указано, как считать местные даты в судовом журнале."},{"number":29,"question":"Если крупномасштабная циркуляция в Северной Атлантике ослабнет и течения будут приносить на север заметно меньше тепла, где наиболее вероятно прямое охлаждающее воздействие этого изменения?","choices":["похолодает в тропических районах","образуется воронка, в которую будут втянуты острова Атлантического океана","произойдёт подъём богатых азотом и фосфором глубинных океанических вод и всплеск продуктивности","похолодает в странах Северной Европы","климаты на Земле выравнятся"],"answer":3,"points":5,"title":"Тепло для Северной Европы","steps":["Океанические течения переносят часть тепла из тропических широт к северу Атлантики. Это влияет на температуру воздуха у северо-запада Европы.","Если такой перенос заметно ослабнет, его прямое воздействие будет охлаждающим для Северной Европы. Задача сравнивает именно этот эффект."],"adaptation":"Различены влияние переноса океанического тепла и общий прогноз климата."},{"number":30,"question":"В таблице показаны показатели пяти экосистем. Какое сочетание лучше всего соответствует степи с умеренным запасом биомассы и заметной ежегодной продукцией?","choices":["столбец А","столбец Б","столбец В","столбец Г","столбец Д"],"answer":2,"points":5,"title":"Показатели степной системы","steps":["У степи нет большой массы древесины, поэтому запас биомассы значительно ниже характерного для леса. При этом травы ежегодно дают заметный прирост и опад.","У варианта В запас 15 т/га, продукция 8 и опад 6. Это промежуточный набор между лесом с большим запасом и системами с очень малым запасом или низкой продукцией."],"adaptation":"Таблица исходных данных перенесена в отдельную схему.","figure":{"src":"assets/chip/2014/9-10-30.webp","detailSrc":"assets/chip/2014/detail/9-10-30.svg","width":480,"height":125,"pixelWidth":680,"pixelHeight":176,"alt":"Таблица для вариантов А, Б, В, Г, Д. Биомасса в т/га: 1000, 123, 15, 1, 6. Продукция в т/га в год: 30, 15, 8, 12, 1. Опад в т/га в год: 224, 14, 6, 10, 1."}}]);
edition.sources.readers = {"tasksUrl":"assets/chip/2014/9-10_2014-reading.pdf"};
register(edition, globalThis.KENGURU_CHOICE_LAYOUTS, {});
